  if (!mounted) return;

  final historyRows = rows.where(_sameBookmaker).toList();

  bool sameHistoryState(
    Map<String, dynamic> newer,
    Map<String, dynamic> older,
  ) {
    return _odd(newer['under_odd']) == _odd(older['under_odd']) &&
        _odd(newer['over_odd']) == _odd(older['over_odd']) &&
        newer['under_closed'] == older['under_closed'] &&
        newer['over_closed'] == older['over_closed'];
  }

  // Opening satırı history içinde
  // aynı oranla tekrar görünmesin.
  if (openingRows.isNotEmpty) {
    final openingRow = openingRows.first;

    bool sameOpeningOdds(Map<String, dynamic> row) {
      return _odd(row['under_odd']) == _odd(openingRow['under_odd']) &&
          _odd(row['over_odd']) == _odd(openingRow['over_odd']);
    }

    for (var i = historyRows.length - 1; i >= 0; i--) {
      if ((historyRows[i]['id'] != null &&
              historyRows[i]['id'].toString() ==
                  openingRow['id']?.toString()) ||
          (historyRows[i]['capture_type'] == 'opening' &&
              historyRows[i]['captured_at'] == openingRow['captured_at'] &&
              sameOpeningOdds(historyRows[i]))) {
        historyRows.removeAt(i);
        break;
      }
    }
  }

  setState(() {
    _markSourceOpeningChronology(openingRows, historyRows);
    _history = historyRows;
    _openingRows = openingRows;
    _bookmakers = bookmakers;
    _loading = false;
    _error = '';
  });
} catch (e) {
  if (!mounted) return;

  setState(() {
    _loading = false;
    _error = e.toString().replaceFirst('Exception: ', '');
  });
